contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool revertedDeposit;
        c.sendMoney(address(this), amount, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedDeposit = true;
        } else {
            revertedDeposit = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        bool revertedWithdraw;
        c.withdraw(amount); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedWithdraw = true;
        } else {
            revertedWithdraw = false;
        }

        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;

        assert(
            revertedDeposit || revertedWithdraw ||
            (beforeC + (afterThis - beforeThis) == afterC + (afterThis - beforeThis) + (afterThis - beforeThis)) ||
            (beforeC + amount == finalC + (finalThis - beforeThis))
        );
    }
}

