pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool revertedDeposit;
        try c.sendMoney(address(this), amount, "") {
            revertedDeposit = false;
        } catch {
            revertedDeposit = true;
        }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        bool revertedWithdraw;
        try c.withdraw(amount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }
        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;
        assertTrue(revertedDeposit || revertedWithdraw ||
            (beforeC + (afterThis - beforeThis) == afterC + (afterThis - beforeThis) + (afterThis - beforeThis)) ||
            (beforeC + amount == finalC + (finalThis - beforeThis)));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
